package com.hbm.machine.reactor.rbmk.failure;
import com.hbm.explosion.ExplosionNT;import com.hbm.explosion.ExplosionNT.ExAttrib;import com.hbm.exposure.HbmExposure;import com.hbm.advancement.HbmAdvancements;import com.hbm.registry.HbmSounds;import com.hbm.entity.LegacyTrackingRange;import net.minecraft.core.BlockPos;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.syncher.SynchedEntityData;import net.minecraft.server.level.ServerLevel;import net.minecraft.sounds.SoundSource;import net.minecraft.world.entity.*;import net.minecraft.world.level.Level;import net.minecraft.world.level.levelgen.Heightmap;
/** Actual EntitySpear: source descending digamma terrain conversion, all-dimension exposure and terminal pulse. */
public final class DigammaSpear extends Entity implements LegacyTrackingRange {
 public int ticksInGround;public static java.util.function.Consumer<DigammaSpear> CLIENT_AIR=spear->{};public DigammaSpear(EntityType<? extends DigammaSpear> type,Level level){super(type,level);noCulling=true;}public DigammaSpear(Level level){this(RbmkFailureContent.SPEAR.get(),level);}@Override public int legacyTrackingRange(){return 1000;}@Override protected void defineSynchedData(SynchedEntityData.Builder builder){}
 @Override public void tick(){xo=getX();yo=getY();zo=getZ();setDeltaMovement(0,-.2,0);var pos=blockPosition();if(level().getBlockState(pos.below()).isAir()){setPos(getX(),getY()-.2,getZ());setYRot(0);setXRot(0);if(level() instanceof ServerLevel world){double x=getX()+random.nextGaussian()*25,z=getZ()+random.nextGaussian()*25,y=world.getHeight(Heightmap.Types.WORLD_SURFACE,(int)Math.floor(x),(int)Math.floor(z))+2;double dx=x-getX(),dz=z-getZ();var attribute=Math.sqrt(dx*dx+dz*dz)<20?ExAttrib.DIGAMMA_CIRCUIT:ExAttrib.DIGAMMA;new ExplosionNT(world,this,x,y,z,7.5F).addAttrib(ExAttrib.NOHURT).addAttrib(ExAttrib.NOPARTICLE).addAttrib(ExAttrib.NODROP).addAttrib(ExAttrib.NOSOUND).addAttrib(attribute).explode();for(var player:world.players()){HbmExposure.contaminateDigamma(player,.05F,false);HbmAdvancements.trigger(player,"digammaKauaiMoho");}}else CLIENT_AIR.accept(this);if(level().getBlockState(pos.below(3)).isAir())ticksInGround=0;}else{ticksInGround++;if(level() instanceof ServerLevel world&&ticksInGround>100){var entities=new java.util.ArrayList<Entity>();world.getAllEntities().forEach(entities::add);for(var entity:entities)if(entity instanceof LivingEntity living)HbmExposure.contaminateDigamma(living,10F,true);world.playSound(null,getX(),getY(),getZ(),HbmSounds.get("weapon.dFlash"),SoundSource.HOSTILE,25000F,1F);RbmkFailureEffects.radial(world,getX(),getY()+7,getZ(),100);discard();}}}
 @Override protected void readAdditionalSaveData(CompoundTag tag){}@Override protected void addAdditionalSaveData(CompoundTag tag){}@Override public boolean shouldRenderAtSqrDistance(double distance){return distance<25000;}
}
